package main

import (
	"testing"
	"time"
)

func TestProbeListPage(t *testing.T) {
	store := NewStore(time.Hour)
	now := time.Unix(1000, 0)
	store.now = func() time.Time { return now }
	// Created out of order; LastSeen follows creation time.
	order := []string{"s3", "s1", "s4", "s2"}
	stamps := map[string]int64{"s3": 1000, "s1": 1001, "s4": 1002, "s2": 1003}
	for _, id := range order {
		now = time.Unix(stamps[id], 0)
		store.Create(id, "u-"+id)
	}

	page, total := store.ListPage(0, 2)
	if total != 4 {
		t.Fatalf("total = %d, want 4", total)
	}
	if len(page) != 2 {
		t.Fatalf("page len = %d, want 2", len(page))
	}
	// Canonical order: s1(1001), s2(1003), s3(1000), s4(1002) -> sorted by LastSeen: s3,s1,s4,s2
	if page[0].ID != "s3" || page[1].ID != "s1" {
		t.Fatalf("first page = [%s %s], want [s3 s1]", page[0].ID, page[1].ID)
	}

	page2, total2 := store.ListPage(2, 2)
	if total2 != 4 || len(page2) != 2 {
		t.Fatalf("page2 = %d items, total %d", len(page2), total2)
	}
	if page2[0].ID != "s4" || page2[1].ID != "s2" {
		t.Fatalf("second page = [%s %s], want [s4 s2]", page2[0].ID, page2[1].ID)
	}

	// Offset beyond the end: empty page, total still 4.
	page3, total3 := store.ListPage(10, 2)
	if len(page3) != 0 || total3 != 4 {
		t.Fatalf("offset past end: %d items, total %d", len(page3), total3)
	}

	// Invalid arguments: empty slice, real total.
	page4, total4 := store.ListPage(-1, 2)
	if len(page4) != 0 || total4 != 4 {
		t.Fatalf("negative offset: %d items, total %d", len(page4), total4)
	}
	page5, total5 := store.ListPage(0, 0)
	if len(page5) != 0 || total5 != 4 {
		t.Fatalf("zero limit: %d items, total %d", len(page5), total5)
	}

	// No mutation.
	if store.Len() != 4 {
		t.Fatalf("store mutated: %d", store.Len())
	}
}
EOF
