package main

import (
	"errors"
	"sort"
	"sync"
	"time"
)

// ErrNotFound is returned when a session id is unknown or has expired.
var ErrNotFound = errors.New("session not found")

// Session is one signed-in user.
type Session struct {
	ID       string
	User     string
	Created  time.Time
	LastSeen time.Time
}

// Store keeps sessions in memory. Everything is lost when the process exits.
type Store struct {
	mu       sync.RWMutex
	sessions map[string]Session
	ttl      time.Duration
	now      func() time.Time
}

// NewStore returns an empty store. Sessions idle for longer than ttl expire.
func NewStore(ttl time.Duration) *Store {
	return &Store{
		sessions: map[string]Session{},
		ttl:      ttl,
		now:      time.Now,
	}
}

// Create records a new session for a user.
func (s *Store) Create(id string, user string) Session {
	s.mu.Lock()
	defer s.mu.Unlock()
	at := s.now()
	session := Session{ID: id, User: user, Created: at, LastSeen: at}
	s.sessions[id] = session
	return session
}

// Get returns a live session and refreshes its last-seen time. An expired
// session is dropped and reported as missing.
func (s *Store) Get(id string) (Session, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	session, ok := s.sessions[id]
	if !ok {
		return Session{}, ErrNotFound
	}
	if s.now().Sub(session.LastSeen) > s.ttl {
		delete(s.sessions, id)
		return Session{}, ErrNotFound
	}
	session.LastSeen = s.now()
	s.sessions[id] = session
	return session, nil
}

// Delete removes a session. Deleting an unknown id is not an error.
func (s *Store) Delete(id string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.sessions, id)
}

// ListPage returns up to limit live sessions starting at offset in
// LastSeen-ascending order (ID ascending on ties), plus the total number of
// live sessions. offset < 0 or limit <= 0 yields an empty page. The store
// is not mutated.
func (s *Store) ListPage(offset, limit int) ([]Session, int) {
	s.mu.RLock()
	now := s.now()
	live := make([]Session, 0, len(s.sessions))
	for _, session := range s.sessions {
		if now.Sub(session.LastSeen) <= s.ttl {
			live = append(live, session)
		}
	}
	s.mu.RUnlock()
	sort.Slice(live, func(i, j int) bool {
		if live[i].LastSeen.Equal(live[j].LastSeen) {
			return live[i].ID < live[j].ID
		}
		return live[i].LastSeen.Before(live[j].LastSeen)
	})
	total := len(live)
	if offset < 0 || limit <= 0 || offset >= total {
		return []Session{}, total
	}
	end := offset + limit
	if end > total {
		end = total
	}
	return live[offset:end], total
}

// Len reports how many sessions are held.
func (s *Store) Len() int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return len(s.sessions)
}

